    return this.data[Object.keys(this.data)[0]];
  } else {
    let result = this.data[Object.keys(this.data)[0]];
    for (const key in this.data) {
      if (this.data[key] * flip < result * flip) {
        result = this.data[key];
      }
    }
    return result;
  }
};

/**
