  p5._validateParameters('select', arguments);
  var res = null;
  var container = getContainer(p);
  if (e[0] === '.') {
    e = e.slice(1);
    res = container.getElementsByClassName(e);
    if (res.length) {
      res = res[0];
    } else {
      res = null;
    }
  } else if (e[0] === '#') {
    e = e.slice(1);
    res = container.getElementById(e);
  } else {
    res = container.getElementsByTagName(e);
    if (res.length) {
      res = res[0];
    } else {
      res = null;
    }
